sysauto_script.script:
(function executeApprovalReminder() {

    var EVENT_NAME = 'x_1549902_asean_0.approval.reminder';
    var PROPERTY_NAME = 'x_1549902_asean_0.approval_reminder_days';

    // Default = 5 days
    var reminderDays = parseInt(gs.getProperty(PROPERTY_NAME, '5'), 10);

    if (isNaN(reminderDays) || reminderDays < 1) {
        reminderDays = 5;
    }

    var cutoff = new GlideDateTime();
    cutoff.addDaysUTC(-reminderDays);

    var approvalGR = new GlideRecord('sysapproval_approver');
    approvalGR.addQuery('state', 'requested');
    approvalGR.addQuery('sys_created_on', '<=', cutoff);
    approvalGR.addNotNullQuery('approver');
    approvalGR.query();

    var count = 0;

    while (approvalGR.next()) {

        // Prevent duplicate reminders
        var eventGR = new GlideRecord('sysevent');
        eventGR.addQuery('name', EVENT_NAME);
        eventGR.addQuery('instance', approvalGR.getUniqueValue());
        eventGR.setLimit(1);
        eventGR.query();

        if (eventGR.hasNext()) {
            continue;
        }

        gs.eventQueue(
            EVENT_NAME,
            approvalGR,
            approvalGR.getValue('approver'),
            approvalGR.getValue('sysapproval')
        );

        count++;
    }

    gs.info('[ASEAN Approval Reminder] ' + count + ' reminder(s) queued.');

})();
